window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[209]={"id":"209","numero":209,"titre":"BPCO","objectifs":[{"id":"209-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la bronchopneumopathie chronique obstructive (BPCO)","contenu":"<p>La <span class=\"kw-def\">BPCO</span> est une <strong>maladie respiratoire chronique</strong>, qui peut être <strong>prévenue et traitée</strong>, et qui se définit par l'association de <strong>2 critères</strong> :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>1. Symptômes respiratoires chroniques (<span class=\"kw-chiffre\">≥ 1</span>)</th>\n            <td><span class=\"kw-clinique\">Dyspnée d'exercice</span> ; <span class=\"kw-clinique\">Toux</span> ; <span class=\"kw-clinique\">Expectoration</span> ; <span class=\"kw-clinique\">Infections respiratoires basses répétées ou traînantes</span></td>\n          </tr>\n          <tr>\n            <th>2. <span class=\"kw-bio\">Trouble ventilatoire obstructif (TVO)</span> persistant <em>après</em> bronchodilatateurs</th>\n            <td>\n              <strong>Significative :</strong> <strong>possible</strong> ✅ (augmentation VEMS > <span class=\"kw-chiffre\">200 mL</span> et > <span class=\"kw-chiffre\">12 %</span> de la valeur initiale)<br>\n              <strong>Complète :</strong> <span class=\"kw-alerte\">jamais</span> ❌ → bascule le diagnostic vers l'asthme\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Point-clé :</strong> <span class=\"kw-bio\">TVO non complètement réversible</span> = critère discriminant majeur <span class=\"kw-bio\">vs</span> <span class=\"kw-clinique\">asthme</span>. La normalisation post-BD (VEMSpost/CVFpost <span class=\"kw-chiffre\">> 0,7</span> ET VEMSpost > <span class=\"kw-chiffre\">80 %</span>) <span class=\"kw-alerte\">élimine</span> la BPCO.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 203 — <span class=\"kw-clinique\">Dyspnée</span> · 204 — Toux · 208 — <span class=\"kw-ci\">Insuffisance respiratoire</span> chronique</em></p>","frequence":4},{"id":"209-2","rang":"A","rubrique":"Définition","titre":"Connaître le principal facteur de risque et les co-morbidités fréquemment associées à la BPCO","contenu":"<p>Le <span class=\"kw-alerte\">tabac</span> est le FR n°1 — présent dans <span class=\"kw-chiffre\">> 80 %</span> des BPCO. C'est l'<strong>unique facteur dont l'arrêt modifie l'histoire naturelle</strong> de la maladie.</p>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span></h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Environnementaux</th>\n            <td>\n              <strong>Tabac :</strong> <span class=\"kw-alerte\">Tabac</span> &gt; <span class=\"kw-chiffre\">80 %</span> des BPCO<br>\n              <strong>Professionnel :</strong> aéro-contaminants <span class=\"kw-etio\">professionnels</span> &gt; <span class=\"kw-chiffre\">15 %</span><br>\n              <strong>Cannabis :</strong> associé au tabac = FR de BPCO + emphysème<br>\n              <strong>Pollution domestique :</strong> biomasse, locaux mal ventilés<br>\n              <strong>Pollution atmosphérique :</strong> déclenchement des <span class=\"kw-clinique\">exacerbations</span><br>\n              <strong>E-c<span class=\"kw-chiffre\">iga</span>rette :</strong> rôle <span class=\"kw-etio\">suspecté</span>\n            </td>\n          </tr>\n          <tr>\n            <th>Génétiques</th>\n            <td>\n              <strong>A1AT :</strong> <span class=\"kw-bio\">Déficit en α-1-antitrypsine</span> → emphysème <strong>pan-lobulaire</strong> précoce et grave si <span class=\"kw-etio\">tabagisme</span> actif associé<br>\n              <strong>TERT :</strong> Mutations du complexe <span class=\"kw-bio\">TERT</span>\n            </td>\n          </tr>\n          <tr>\n            <th>Début de vie</th>\n            <td><strong>Périnatal :</strong> prématurité ; petit poids de naissance ; infections respiratoires de la petite enfance ; <span class=\"kw-etio\">tabagisme</span> passif / tabagisme actif précoce ; asthme non contrôlé</td>\n          </tr>\n          <tr>\n            <th>Infections</th>\n            <td>Infections respiratoires basses de la petite enfance ; <span class=\"kw-etio\">Tuberculose</span> ; <span class=\"kw-etio\">VIH</span> (mécanisme incertain)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Comorbidités</span> fréquentes</h4>\n      <table >\n        <thead><tr><th>Appareil</th><th>Comorbidités</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Cardio-vasculaires</th>\n            <td><span class=\"kw-alerte\">1ère cause de mortalité 🏴‍☠️</span> — coronaropathie, <span class=\"kw-clinique\">insuffisance cardiaque</span>, <span class=\"kw-clinique\">HTA</span></td>\n          </tr>\n          <tr>\n            <th>Cancer</th>\n            <td><span class=\"kw-alerte\">Cancer broncho-pulmonaire ×3</span> <span class=\"kw-bio\">vs</span> population générale</td>\n          </tr>\n          <tr>\n            <th>Osseuse</th>\n            <td><span class=\"kw-clinique\">Ostéoporose</span></td>\n          </tr>\n          <tr>\n            <th>Métabolique / Nutritionnel</th>\n            <td>Dénutrition ou <span class=\"kw-etio\">obésité</span> ; déconditionnement musculaire (amyotrophie) ; <span class=\"kw-bio\">anémie</span></td>\n          </tr>\n          <tr>\n            <th>Psychiatrique</th>\n            <td>Anxiété, dépression</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>🏴‍☠️ <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">comorbidités</span> cardio-vasculaires sont la 1ère cause de <span class=\"kw-def\">mortalité</span> dans la BPCO.</strong> Ne pas se focaliser sur le poumon — un bilan CV est systématique.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction Tabac · 309 — Tumeurs du poumon · 222 — FDR cardiovasculaire · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span></em></p>","frequence":3},{"id":"209-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic positif et du diagnostic différentiel","contenu":"<h4>1. Suspicion clinique</h4>\n      <p>Signes physiques <strong>absents pendant des années</strong> ou limités à des ronchi (<span class=\"kw-clinique\">râles bronchiques</span>) → la suspicion repose souvent sur l'<strong>interrogatoire</strong> + <span class=\"kw-imagerie\">RXT</span>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Signes fonctionnels</th>\n            <td>\n              <strong><span class=\"kw-clinique\">Dyspnée</span> :</strong> <span class=\"kw-clinique\">Dyspnée d'effort progressive</span> = symptôme <strong>principal</strong>, à rechercher chez tout fumeur, évaluée par l'échelle <span class=\"kw-bio\">mMRC</span><br>\n              <strong><span class=\"kw-clinique\">Toux</span> :</strong> <span class=\"kw-clinique\">Toux</span> ± <span class=\"kw-clinique\">expectorations</span><br>\n              <strong>Infections :</strong> <span class=\"kw-clinique\">Infections respiratoires basses</span> répétées ou traînantes\n            </td>\n          </tr>\n          <tr>\n            <th>Signes de distension</th>\n            <td>\n              <strong>Thorax :</strong> en tonneau / carré / cloche<br>\n              <strong>Sus-sternal :</strong> raccourcissement du segment sus-sternal <span class=\"kw-chiffre\">&lt; 3 cm</span><br>\n              <strong><span class=\"kw-clinique\">Diamètre</span> :</strong> augmentation du diamètre antéro-postérieur<br>\n              <strong>Posture :</strong> position du tripode<br>\n              <strong>Signe de Hoover :</strong> diminution du diamètre transversal inférieur du thorax à l'inspiration — <span class=\"kw-alerte\">ce n'est PAS un signe de gravité</span> ❌, juste de distension\n            </td>\n          </tr>\n          <tr>\n            <th>Signes d'obstruction</th>\n            <td>\n              <strong>Expiration :</strong> expiration abdominale active<br>\n              <strong>Lèvres pincées :</strong> respiration <strong>lèvres pincées</strong> = signe d'obstruction bronchique distale<br>\n              <strong>Auscultation :</strong> ronchi ; <span class=\"kw-clinique\">sibilants</span> diffus ; sifflements audibles sans stéthoscope\n            </td>\n          </tr>\n          <tr>\n            <th>Signes de dysfonction diaphragmatique</th>\n            <td>\n              <strong>Tirages :</strong> intercostal / sus-claviculaire / sus-sternal<br>\n              <strong>Paradoxe :</strong> <span class=\"kw-alerte\">Respiration abdominale paradoxale</span> = gravité en aigu<br>\n              <strong>Pouls respiratoire :</strong> palpable<br>\n              <strong>Signe de Campbell :</strong> descente du cartilage thyroïde à l'inspiration\n            </td>\n          </tr>\n          <tr>\n            <th>Signe d'emphysème</th>\n            <td>Diminution bilatérale du <span class=\"kw-clinique\">murmure vésiculaire</span></td>\n          </tr>\n          <tr>\n            <th>Si IRC évoluée</th>\n            <td>Signes d'<span class=\"kw-clinique\">hypercapnie</span> ; <span class=\"kw-clinique\">HTAP</span> ; <span class=\"kw-clinique\">dysfonction cardiaque droite</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2. Confirmation paraclinique — spirométrie post-BD</h4>\n      <p>La confirmation de BPCO <span class=\"kw-alerte\">REQUIERT</span> une <span class=\"kw-bio\">spirométrie</span> avec mesure du <span class=\"kw-bio\">VEMS</span> et de la <span class=\"kw-bio\">CVF</span> <strong>avant et après bronchodilatateurs</strong>, <span class=\"kw-alerte\">en dehors d'une exacerbation</span>.</p>\n      <table >\n        <thead><tr><th>Statut</th><th>Critère EFR</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Indispensable</th>\n            <td><span class=\"kw-bio\">VEMS / CVF &lt; <span class=\"kw-chiffre\">70 %</span> post-BD</span> = TVO non complètement réversible</td>\n          </tr>\n          <tr>\n            <th>Possible (réversibilité significative)</th>\n            <td>Augmentation VEMS &gt; <span class=\"kw-chiffre\">200 mL</span> <strong>ET</strong> &gt; <span class=\"kw-chiffre\">12 %</span> par rapport à la valeur initiale après BDCA ou test aux <span class=\"kw-ttt\">corticoïdes</span> (<span class=\"kw-chiffre\">2 semaines</span>)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-alerte\">Exclut la BPCO</span></th>\n            <td>Réversibilité <strong>complète</strong> : normalisation <span class=\"kw-bio\">VEMSpost/CVFpost &gt; 0,7</span> ET <span class=\"kw-bio\">VEMSpost &gt; <span class=\"kw-chiffre\">80 %</span></span> → oriente vers l'<span class=\"kw-clinique\">asthme</span></td>\n          </tr>\n          <tr>\n            <th>Piège EFR</th>\n            <td>Le <span class=\"kw-chiffre\">70 %</span> = % de VEMS mesuré / CVF mesurée — <span class=\"kw-alerte\">PAS</span> un % de valeur théorique ❌</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Réversibilité complète = NON BPCO.</strong> Si VEMSpost/CVFpost &gt; 0,7 → diagnostic = <span class=\"kw-clinique\">asthme</span>.\n      </div>\n\n      <h4>3. <span class=\"kw-def\">Diagnostic différentiel</span> principal — asthme</h4>\n      <table >\n        <thead><tr><th>Critère</th><th>BPCO</th><th>Asthme</th></tr></thead>\n        <tbody>\n          <tr><th>Définition</th><td>Obstruction <span class=\"kw-bio\">non complètement réversible</span></td><td>Obstruction totalement / presque totalement réversible</td></tr>\n          <tr><th><span class=\"kw-def\">Terrain</span></th><td>Fumeur, &gt; <span class=\"kw-chiffre\">40 ans</span></td><td>Adulte jeune, <span class=\"kw-etio\">atopique</span></td></tr>\n          <tr><th>Rhinosinusite chronique</th><td>Inconstante</td><td>Quasi constante (parfois polypose)</td></tr>\n          <tr><th>Histoire naturelle</th><td>&gt;<span class=\"kw-chiffre\"> 40 ans</span>, aggravation progressive vers IRC, exacerbations</td><td>Début enfance, symptômes brefs et réversibles</td></tr>\n          <tr><th>Clinique typique</th><td><span class=\"kw-clinique\">Dyspnée</span> d'effort puis de repos ± bronchite chronique</td><td>Symptômes variables et réversibles, périodes asymptomatiques</td></tr>\n          <tr><th>Imagerie</th><td><span class=\"kw-imagerie\">Emphysème</span> (inconstant)</td><td>Normale le plus souvent</td></tr>\n          <tr><th>EFR</th><td><span class=\"kw-alerte\">TVO permanent</span>, spirométrie <strong>jamais normale</strong></td><td>TVO réversible, spirométrie peut être normale, <span class=\"kw-bio\">HRB</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Attention, trompeur :</strong> BPCO et asthme peuvent être <strong>associés</strong>. De nombreux asthmatiques fument ; certains asthmatiques sévères non-fumeurs ont un TVO peu réversible.\n      </div>\n\n      <p>Autres DD plus rares : <span class=\"kw-clinique\">dilatation des bronches</span>, <span class=\"kw-clinique\">mucoviscidose</span>, bronchiolites oblitérantes post-greffe ou <span class=\"kw-clinique\">MICI</span>, mutations rares (SPC, ABCA3, complexe télomérase).</p>\n\n      <h4>4. Entités nosologiques associées à un TVO</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Bronchite chronique<br><em>(voies aériennes)</em></th>\n            <td>\n              <strong>Fréquence :</strong> concerne <span class=\"kw-chiffre\">50 %</span> des fumeurs<br>\n              <strong>Définition <em>clinique</em> :</strong> <span class=\"kw-clinique\">toux</span> productive quotidienne <span class=\"kw-chiffre\">≥ 3 mois/an</span> pendant <span class=\"kw-chiffre\">≥ 2 années consécutives</span>\n            </td>\n          </tr>\n          <tr>\n            <th>Emphysème<br><em>(poumon)</em></th>\n            <td>\n              <strong>Définition <em>anatomopathologique</em> :</strong> élargissement anormal et permanent des espaces aériens distaux avec <strong>destruction des parois alvéolaires sans fibrose</strong> ❌<br>\n              <strong>Imagerie :</strong> hypodensités + bulles &gt; <span class=\"kw-chiffre\">1 cm</span><br>\n              <strong>EFR :</strong> <span class=\"kw-bio\">DLCO / TLCO &lt; <span class=\"kw-chiffre\">70 %</span></span><br>\n              <strong>Centrolobulaire :</strong> destruction centrée sur la bronchiole, hypoxémie par inégalité V/Q<br>\n              <strong>Pan-lobulaire :</strong> destruction de l'ensemble du lobule, hypoxémie de repos tardive — typique du <span class=\"kw-bio\">déficit en A1AT</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 188 — Asthme - Rhinite · 203 — <span class=\"kw-clinique\">Dyspnée</span> · 207 — Opacité intra-thoracique Adulte/Enfant · 208 — <span class=\"kw-ci\">Insuffisance respiratoire</span> chronique</em></p>","frequence":5},{"id":"209-4","rang":"A","rubrique":"Identifier une urgence","titre":"Identifier une exacerbation/décompensation de BPCO, en évaluer les signes de gravité","contenu":"<h4>1. Définition</h4>\n      <p><span class=\"kw-def\">Évènement aigu</span> avec aggravation durable des symptômes respiratoires <span class=\"kw-chiffre\">&gt; 24 h</span> et <span class=\"kw-chiffre\">&lt; 14 jours</span>, imposant une modification thérapeutique.</p>\n      <ul>\n        <li>Exacerbation <strong>sévère</strong> = engage le <span class=\"kw-alerte\">pronostic vital</span> : DRA, hypoxémie profonde, acidose respiratoire décompensée.</li>\n        <li>Peut être <strong>inaugurale</strong> (BPCO non connue) → la démarche diagnostique est alors celle d'une <span class=\"kw-clinique\">IRA</span>.</li>\n      </ul>\n\n      <h4>2. <span class=\"kw-def\">Diagnostic positif</span></h4>\n      <ul>\n        <li>Aggravation des symptômes &gt;<span class=\"kw-chiffre\"> 24 h</span> et &lt; 14 j : <span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">dyspnée</span>, volume / purulence de l'<span class=\"kw-clinique\">expectoration</span></li>\n        <li>Conduisant à une modification thérapeutique : augmentation des <span class=\"kw-ttt\">BDCA</span> ± <span class=\"kw-ttt\">corticothérapie systémique</span> ± <span class=\"kw-ttt\">ATB</span></li>\n      </ul>\n\n      <h4>3. <span class=\"kw-alerte\">Signes de gravité</span></h4>\n      <table >\n        <thead><tr><th><span class=\"kw-alerte\">Détresse</span></th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Respiratoire</th>\n            <td>\n              <strong><span class=\"kw-clinique\">Tachypnée</span> :</strong> <span class=\"kw-clinique\">Tachypnée</span><br>\n              <strong>Parole :</strong> difficulté à la parole<br>\n              <strong><span class=\"kw-clinique\">Cyanose</span> :</strong> <span class=\"kw-clinique\">Cyanose</span><br>\n              <strong>Balancement :</strong> balancement thoraco-abdominal (paradoxe abdominal + tachypnée)<br>\n              <strong><span class=\"kw-clinique\">Bradypnée</span> :</strong> <span class=\"kw-alerte\">Bradypnée = faillite diaphragmatique = extrême gravité</span> → <span class=\"kw-ttt\">ventilation mécanique</span> urgente\n            </td>\n          </tr>\n          <tr>\n            <th>Cardio-vasculaire</th>\n            <td>\n              <strong><span class=\"kw-etio\">HTA</span> :</strong> <span class=\"kw-clinique\">HTA</span><br>\n              <strong><span class=\"kw-clinique\">Sueurs</span> :</strong> sueurs = signes d'<span class=\"kw-clinique\">hypercapnie</span><br>\n              <strong>Hypoperfusion :</strong> signes d'<span class=\"kw-alerte\">hypoperfusion périphérique</span> : froideur des extrémités, marbrures, pouls filants → hypoxie tissulaire\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>🚨 <span class=\"kw-clinique\">Bradypnée</span> + balancement abdominal = extrême gravité.</strong> Indication de <span class=\"kw-ttt\">ventilation mécanique</span> urgente.\n      </div>\n\n      <h4>4. Orientation : ambulatoire <span class=\"kw-bio\">vs</span> <span class=\"kw-alerte\">hospitalisation</span> 🏥</h4>\n      <ul>\n        <li><strong>Ambulatoire</strong> : la majorité des cas, pas de <span class=\"kw-alerte\">signes de gravité</span>, PEC sans bilan paraclinique.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Critère</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-def\">Stade</span></th><td><span class=\"kw-alerte\">BPCO stade GOLD 3 ou 4</span></td></tr>\n          <tr><th>Clinique</th><td><span class=\"kw-alerte\">Signes de gravité</span> immédiate ; aggravation rapide ; <span class=\"kw-clinique\">dyspnée</span> à l'état basal (pour s'habiller) ; apparition d'une <span class=\"kw-clinique\">arythmie</span></td></tr>\n          <tr><th>Échec / Incertitude</th><td>Absence de réponse au TT initial ; incertitude diagnostique</td></tr>\n          <tr><th><span class=\"kw-def\">Terrain</span></th><td>Âge <span class=\"kw-chiffre\">&gt; 70 ans</span> ; fragilité ; absence de soutien à domicile ; OLD ; ventilation à domicile</td></tr>\n          <tr><th>ATCD / <span class=\"kw-def\">Comorbidités</span></th><td>ATCD de réa pour exacerbation ; <span class=\"kw-def\">comorbidités</span> CV, <span class=\"kw-etio\">alcoolisme</span>, neuro, psy</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 154 — Infection bronchopulmonaire communautaire · 234 — Insuffisance cardiaque · 226 — Thrombose veineuse profonde - EP · 360 — Pneumothorax (rob)</em></p>","frequence":4},{"id":"209-5","rang":"B","rubrique":"Etiologies","titre":"Connaître les facteurs précipitants d’une décompensation/exacerbation de BPCO","contenu":"<p>La cause est <strong>souvent non identifiée</strong>. Quand elle l'est, l'origine est dans <span class=\"kw-chiffre\">&gt; 50 %</span> des cas <span class=\"kw-etio\">infectieuse</span>.</p>\n\n      <table >\n        <thead><tr><th>Catégorie</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Environnement</th>\n            <td>Pic de pollution ; <span class=\"kw-etio\">tabagisme</span> massif</td>\n          </tr>\n          <tr>\n            <th>Infection (&gt;<span class=\"kw-chiffre\"> 50 %</span>)</th>\n            <td>\n              <strong><span class=\"kw-etio\">Virale</span> :</strong> <span class=\"kw-etio\">influenza</span> ; <span class=\"kw-etio\">rhinovirus</span> ; <span class=\"kw-etio\">coronavirus</span> ; <span class=\"kw-etio\">adénovirus</span><br>\n              <strong><span class=\"kw-etio\">Bactérienne</span></strong> (<span class=\"kw-bio\">purulence verdâtre franche</span> en faveur) <strong>:</strong> <span class=\"kw-etio\">Haemophilus influenzae</span> ; <span class=\"kw-etio\">Streptococcus pneumoniae</span> ; <span class=\"kw-etio\">Moraxella catarrhalis</span><br>\n              <strong>Documentation :</strong> rarement nécessaire (VAB chroniquement colonisées)\n            </td>\n          </tr>\n          <tr>\n            <th>Critères d'Anthonisen<br><em>(aspécifiques)</em></th>\n            <td>Augmentation du volume des <span class=\"kw-clinique\">expectorations</span> ; de leur purulence ; de la dyspnée</td>\n          </tr>\n          <tr>\n            <th>DD / causes associées</th>\n            <td>\n              <strong>Cardio-pulmonaires :</strong> <span class=\"kw-clinique\">PAC</span> ; <span class=\"kw-clinique\">OAP</span> ; <span class=\"kw-clinique\">embolie pulmonaire</span> ; <span class=\"kw-clinique\">pneumothorax</span><br>\n              <strong>Traitement <span class=\"kw-ci\">contre-indiqué</span> :</strong> <span class=\"kw-ci\">sédatifs</span> ; <span class=\"kw-ci\">oxygène à haut débit</span> ; <span class=\"kw-ci\">opiacés</span><br>\n              <strong><span class=\"kw-etio\">Iatrogène</span> / traumatique :</strong> <span class=\"kw-ttt\">chirurgie</span> thoracique / abdominale ; traumatisme thoracique ; fracture / tassement vertébral\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-etio\">Pseudomonas</span> aeruginosa — terrains à risque ⚠️</strong>\n        <ul>\n          <li>Patients sévères : <span class=\"kw-bio\">VEMS &lt; <span class=\"kw-chiffre\">30 %</span></span> prédit</li>\n          <li>Présence de <span class=\"kw-imagerie\">bronchectasies</span></li>\n          <li>Hospitalisations antérieures avec ATB à large spectre</li>\n          <li><span class=\"kw-ttt\">Corticothérapie systémique</span> chronique</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire · 226 — Thrombose veineuse profonde - EP · 360 — Pneumothorax (rob) · 234 — <span class=\"kw-ci\">Insuffisance cardiaque</span></em></p>","frequence":3},{"id":"209-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les signes paracliniques de gravité","contenu":"<p>Le bilan paraclinique <strong>ne concerne que <span class=\"kw-clinique\">les</span> patients hospitalisés</strong> 🏥.</p>\n\n      <h4>Bilan paraclinique</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Systématique</th>\n            <td><span class=\"kw-clinique\">ECG</span> ; <span class=\"kw-bio\">GDS</span> ; <span class=\"kw-imagerie\">RXT</span> ; biologie (<span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>)</td>\n          </tr>\n          <tr>\n            <th>Selon contexte</th>\n            <td><span class=\"kw-imagerie\">TDM</span> ; <span class=\"kw-imagerie\">angio-TDM</span> ; <span class=\"kw-bio\">BNP</span> ; <span class=\"kw-bio\">troponine</span> ; <span class=\"kw-imagerie\">ETT</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-bio\">PCR</span> <span class=\"kw-etio\">virale</span></th>\n            <td>Aspiration trachéale ou écouvillon nasopharyngé en période épidémique</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-bio\">ECBC</span> ou prélèvement profond</th>\n            <td><strong>Indications :</strong> échec ATB préalable ; ATCD de <span class=\"kw-etio\">colonisation</span> à <span class=\"kw-etio\">Pseudomonas</span> ; BPCO sévère motivant l'<span class=\"kw-alerte\">hospitalisation</span> ; réanimation / soins intensifs ; immunodépression</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Signes paracliniques de gravité +++</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Acidose respiratoire</span> : <span class=\"kw-bio\">pH &lt; <span class=\"kw-chiffre\">7,35</span></span> sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">GDS</span> → indication de <span class=\"kw-ttt\">VNI</span></li>\n        <li><span class=\"kw-alerte\">Hypoxémie profonde</span> : <span class=\"kw-bio\">SpO2</span> / <span class=\"kw-bio\">PaO2</span> basse → <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span> majeur, motif d'<span class=\"kw-ttt\">oxygénothérapie</span></li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>⚡ <span class=\"kw-bio\">pH</span> &lt; <span class=\"kw-chiffre\">7,35</span> = indication de <span class=\"kw-ttt\">VNI</span>.</strong> La <span class=\"kw-ttt\">VNI</span> est le traitement de <span class=\"kw-chiffre\">1ère intention</span> de l'acidose respiratoire de l'exacerbation.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":1},{"id":"209-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d’imagerie devant une BPCO","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-imagerie\">Radiographie thoracique</span></th>\n            <td>\n              <p>Pas d'intérêt pour le <strong><span class=\"kw-def\">diagnostic positif</span> strict</strong> mais peut le faire <strong>suspecter</strong>.</p>\n              <strong>Exacerbation :</strong> suspicion d'<span class=\"kw-clinique\">exacerbation</span><br>\n              <strong>DD :</strong> recherche de <span class=\"kw-clinique\">pneumonie</span> ; <span class=\"kw-clinique\">OAP</span> ; <span class=\"kw-clinique\">pneumothorax</span> ; épanchement pleural<br>\n              <strong>Bilan :</strong> bilan d'<span class=\"kw-alerte\">hospitalisation</span>\n            </td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\">TDM thoracique</span></th>\n            <td>\n              <p><strong>Non systématique.</strong> Indications dans le bilan initial des <strong>formes sévères</strong> :</p>\n              <strong>Emphysème :</strong> visualisation de l'<span class=\"kw-imagerie\">emphysème</span><br>\n              <strong>Bronchectasies :</strong> recherche de <span class=\"kw-imagerie\">bronchectasies</span><br>\n              <strong>Cancer :</strong> <span class=\"kw-alerte\">Dépistage du cancer broncho-pulmonaire</span><br>\n              <strong>Coronaires :</strong> identifier des <span class=\"kw-imagerie\">calcifications coronaires</span> → recherche d'une coronaropathie si non connue\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-imagerie\">TDM</span> = <span class=\"kw-clinique\">porte d'entrée</span> du <span class=\"kw-def\">dépistage</span> du cancer bronchique chez le BPCO</strong> (risque ×3). À discuter au cas par cas dans <span class=\"kw-clinique\">les</span> formes sévères.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant · 309 — Tumeurs du poumon</em></p>","frequence":1},{"id":"209-8","rang":"B","rubrique":"Contenu multimédia","titre":"Radiographie thoracique de BPCO","contenu":"<p>La <span class=\"kw-imagerie\">RXT</span> n'a pas d'intérêt pour le <span class=\"kw-def\">diagnostic positif</span> de BPCO mais peut le <strong>suspecter</strong>. Deux grandes catégories de signes : <span class=\"kw-imagerie\">hyperclarté pulmonaire</span> et <span class=\"kw-imagerie\">distension thoracique</span>.</p>\n\n      <table >\n        <thead><tr><th>Signe</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-imagerie\">Hyperclarté pulmonaire</span> <em>(+ noir)</em></th>\n            <td>Traduit une <strong>diminution de la vascularisation</strong> pulmonaire = signe d'<span class=\"kw-imagerie\">emphysème</span></td>\n          </tr>\n          <tr>\n            <th>Distension — <strong><span class=\"kw-def\">incidence</span> de face</strong></th>\n            <td>\n              <strong>Arcs costaux :</strong> visualisation de <span class=\"kw-chiffre\">≥ 7 arcs costaux</span><br>\n              <strong>Côtes :</strong> <span class=\"kw-imagerie\">Horizontalisation des côtes</span><br>\n              <strong>Espaces intercostaux :</strong> élargissement des espaces intercostaux\n            </td>\n          </tr>\n          <tr>\n            <th>Distension — <strong><span class=\"kw-def\">incidence</span> de profil</strong></th>\n            <td>\n              <strong>Coupoles :</strong> <span class=\"kw-imagerie\">Aplatissement des coupoles diaphragmatiques</span><br>\n              <strong>Espaces clairs :</strong> augmentation des espaces clairs <strong>rétro-sternal</strong> et <strong>rétro-cardiaque</strong><br>\n              <strong><span class=\"kw-clinique\">Diamètre</span> AP :</strong> augmentation du diamètre thoracique antéro-postérieur = <strong>thorax en tonneau</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/209/rp-bpco-face.png\" alt=\"Deux radiographies de thorax de face : à gauche radiographie normale ; à droite distension thoracique avec augmentation du nombre d'espaces intercostaux au-dessus du diaphragme (plus de 7) et aplatissement des coupoles diaphragmatiques\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies de thorax de face</span> (patients distincts). <strong>À gauche :</strong> <span class=\"kw-imagerie\">radiographie</span> <span class=\"kw-radio\">normale</span>. <strong>À droite :</strong> <span class=\"kw-def\">distension thoracique</span> — <span class=\"kw-radio\">augmentation du nombre d'espaces intercostaux au-dessus du diaphragme (&gt; 7)</span> et <span class=\"kw-radio\">aplatissement des coupoles diaphragmatiques</span>. La <span class=\"kw-imagerie\">RXT</span> ne fait pas le diagnostic de BPCO et peut être normale. Source : banque imagerie « Imagerie à connaître » (item 209).</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/209/rp-bpco-profil.png\" alt=\"Deux radiographies de thorax de profil : à gauche radiographie normale ; à droite distension thoracique avec augmentation des espaces clairs rétro-sternal et rétro-cardiaque\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographies de thorax de profil</span> (2 patients distincts). <strong>À gauche :</strong> radiographie <span class=\"kw-radio\">normale</span>. <strong>À droite :</strong> <span class=\"kw-def\">distension thoracique</span> — <span class=\"kw-radio\">augmentation des espaces clairs rétro-sternal et rétro-cardiaque</span>. Source : banque imagerie « Imagerie à connaître » (item 209).</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">\n        <strong>La <span class=\"kw-imagerie\">RXT</span> peut être normale chez un BPCO peu évolué.</strong> Une <span class=\"kw-imagerie\">RXT</span> sans anomalie n'élimine pas le diagnostic.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":4},{"id":"209-9","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de la BPCO","contenu":"<table >\n        <thead><tr><th>Indicateur</th><th>Chiffre</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-def\">Prévalence</span> en France</th>\n            <td><span class=\"kw-chiffre\">5-10 %</span> des <span class=\"kw-chiffre\">&gt; 45 ans</span> ≈ <span class=\"kw-chiffre\">3,5 millions</span> ; dont <span class=\"kw-chiffre\">1 million asymptomatique</span> → <span class=\"kw-alerte\">2/3 ignorent leur BPCO</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-def\">Mortalité</span> mondiale</th>\n            <td><span class=\"kw-alerte\">4ème cause</span> de <span class=\"kw-def\">mortalité</span> 🏴‍☠️ — projection <span class=\"kw-alerte\">3ème d'ici 2030</span></td>\n          </tr>\n          <tr>\n            <th>Mortalité française</th>\n            <td><span class=\"kw-chiffre\">&gt; 18 000 décès / an</span> en France (2022)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-clinique\">Évolution</span> naturelle</th>\n            <td>Vers l'<span class=\"kw-clinique\">insuffisance respiratoire chronique</span> en l'absence de <span class=\"kw-ttt\">sevrage</span> tabagique</td>\n          </tr>\n          <tr>\n            <th>Cancer du poumon</th>\n            <td><span class=\"kw-alerte\">Risque ×3</span> chez le BPCO <span class=\"kw-bio\">vs</span> population générale</td>\n          </tr>\n          <tr>\n            <th>Impact</th>\n            <td>Problème de santé publique majeur (morbi-<span class=\"kw-def\">mortalité</span> + dépenses de santé élevées)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>2/3 des patients BPCO ignorent leur diagnostic.</strong> Spirométrie à proposer systématiquement chez tout <span class=\"kw-clinique\">fumeur &gt; 40 ans symptomatique</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction Tabac · 309 — Tumeurs du poumon</em></p>","frequence":2},{"id":"209-10","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de l’initiation du traitement symptomatique en urgence","contenu":"<p>4 étapes hiérarchisées du traitement symptomatique en <span class=\"kw-alerte\">urgence</span> — <span class=\"kw-ttt\">oxygénothérapie</span> → conditionnement → <span class=\"kw-ttt\">BDCA</span> → <span class=\"kw-ttt\">ventilation mécanique</span> si besoin.</p>\n\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>1️⃣ <span class=\"kw-ttt\">Oxygénothérapie</span></th>\n            <td>\n              <strong>Motif :</strong> <span class=\"kw-alerte\">hospitalisation</span> 🏥<br>\n              <strong>Objectif :</strong> <span class=\"kw-bio\">SpO2 <span class=\"kw-chiffre\">88-92 %</span></span><br>\n              <strong>Débit :</strong> <span class=\"kw-alerte\">titré</span> (pas haut débit aveugle)<br>\n              <strong><span class=\"kw-def\">Surveillance</span> :</strong> <span class=\"kw-bio\">GDS</span> si hypercapnie → détecter rare aggravation acidose respiratoire\n            </td>\n          </tr>\n          <tr>\n            <th>2️⃣ Conditionnement</th>\n            <td>Patient au repos ; demi-assis ; monitoring <span class=\"kw-imagerie\">ECG</span> + PA non invasive ; voie veineuse périphérique</td>\n          </tr>\n          <tr>\n            <th>3️⃣ <span class=\"kw-ttt\">BDCA</span> <em>(traitement essentiel, voie inhalée exclusive)</em></th>\n            <td>\n              <strong><span class=\"kw-chiffre\">1ère intention</span> :</strong> <span class=\"kw-ttt\">β2-agonistes courte durée</span> = <span class=\"kw-ttt\">salbutamol</span><span class=\"kw-chiffre\"> 5 mg</span> ou <span class=\"kw-ttt\">terbutaline</span><span class=\"kw-chiffre\"> 5 mg</span>, <span class=\"kw-chiffre\">4 à 6×/j</span><br>\n              <strong>Association possible :</strong> <span class=\"kw-ttt\">Anti-cholinergiques courte durée</span> = <span class=\"kw-ttt\">bromure d'ipratropium</span><span class=\"kw-chiffre\"> 0,5 mg</span>, <span class=\"kw-chiffre\">3 à 4×/j</span><br>\n              <strong>Administration :</strong> <strong>nébulisation</strong> à l'hôpital ; <strong>chambre d'inhalation</strong> à domicile\n            </td>\n          </tr>\n          <tr>\n            <th>4️⃣ <span class=\"kw-ttt\">Ventilation mécanique</span></th>\n            <td>\n              <strong>Motif :</strong> <span class=\"kw-alerte\">hospitalisation</span> 🏥 — indiquée si <span class=\"kw-alerte\">acidose respiratoire pH &lt; <span class=\"kw-chiffre\">7,35</span></span> et/ou <span class=\"kw-alerte\">signes de gravité</span><br>\n              <strong><span class=\"kw-chiffre\">1ère intention</span> :</strong> <span class=\"kw-ttt\">VNI</span> par masque facial<br>\n              <strong>Si échec ou CI <span class=\"kw-ttt\">VNI</span> :</strong> <span class=\"kw-ttt\">intubation endotrachéale</span><br>\n              <strong>À noter :</strong> <em><span class=\"kw-alerte\">Coma</span> hypercapnique = PAS une CI à la VNI</em> (peut être réversible avec VNI bien conduite)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>⚡ Piège <span class=\"kw-ttt\">oxygénothérapie</span> BPCO</strong> — L'administration insuffisante d'O2 par peur de majorer l'hypercapnie est une <strong>erreur fréquente <span class=\"kw-ci\">à éviter</span></strong> : l'<span class=\"kw-alerte\">hypoxémie grave non traitée</span> est une <strong><span class=\"kw-alerte\">urgence</span> immédiate</strong> (<span class=\"kw-alerte\">arrêt cardiaque</span> hypoxique). L'<span class=\"kw-clinique\">hypercapnie</span> est une urgence différée (plusieurs heures).\n        <br><br>\n        <strong>3 mécanismes d'hypercapnie sous O2 :</strong>\n        <ol>\n          <li><strong>Effet espace mort</strong> : levée de la vasoconstriction hypoxique → zones d'espace mort alvéolaire</li>\n          <li><strong>Effet Haldane</strong> : Hb mieux saturée → diminution affinité Hb pour CO2 → libération de CO2</li>\n          <li><strong>Hypoventilation pure</strong> : perte de la stimulation par <span class=\"kw-bio\">PaCO2</span> chronique → la régulation passe par <span class=\"kw-clinique\">les</span> chimiorécepteurs carotidiens sensibles à <span class=\"kw-bio\">PaO2</span> → ↑ excessive de <span class=\"kw-bio\">PaO2</span> → ↓ ventilation minute</li>\n        </ol>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë</em></p>","frequence":3},{"id":"209-11","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","contenu":"<h4>1. Objectifs thérapeutiques</h4>\n      <ul>\n        <li><strong>Diminuer <span class=\"kw-clinique\">les</span> handicaps</strong> : améliorer la <span class=\"kw-clinique\">dyspnée</span>, la capacité d'exercice, la qualité de vie</li>\n        <li><strong>Réduire <span class=\"kw-clinique\">les</span> risques futurs</strong> : exacerbations (gravité + hospitalisations), <span class=\"kw-def\">mortalité</span>, déclin du <span class=\"kw-bio\">VEMS</span>, <span class=\"kw-clinique\">évolution</span> vers l'<span class=\"kw-clinique\">IRC</span></li>\n      </ul>\n\n      <h4>2. Mesures hygiéno-diététiques</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Sevrage tabagique</span> = <strong>seule mesure qui modifie l'histoire naturelle</strong> de la BPCO. Interrompt la progression de l'obstruction et retarde l'IRC.</li>\n        <li>Éviction des risques professionnels</li>\n        <li>Activité physique : <span class=\"kw-chiffre\">30 min/j</span> ou <span class=\"kw-chiffre\">&gt; 2 h/semaine</span> (améliore la <span class=\"kw-def\">mortalité</span>)</li>\n      </ul>\n\n      <table >\n        <thead><tr><th>Vaccin</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><th>Anti-<span class=\"kw-ttt\">COVID-19</span></th><td>Recommandé</td></tr>\n          <tr><th>Anti-<span class=\"kw-ttt\">grippal</span></th><td>Annuel</td></tr>\n          <tr><th>Anti-<span class=\"kw-ttt\">pneumococcique</span></th><td>1 dose <span class=\"kw-ttt\">VPC 13</span> puis <span class=\"kw-chiffre\">2 mois</span> après 1 dose <span class=\"kw-ttt\">VPP 23</span> ; rappel à<span class=\"kw-chiffre\"> 5 ans</span> possible si risque persistant</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3. Traitement de fond inhalé — stratégie par étapes</h4>\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">BDLA</span> sont la <strong>base</strong> du traitement. Les <span class=\"kw-ttt\">CSI</span> ne sont <span class=\"kw-alerte\">jamais en monothérapie</span> ❌, toujours associés à un <span class=\"kw-ttt\">β2-LA</span>.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><th>Tous les cas <em>(pas de <span class=\"kw-clinique\">dyspnée</span> quotidienne ni exacerbation)</em></th><td><span class=\"kw-ttt\">BDCA</span> à la demande (β2 ou anticholinergique)</td></tr>\n          <tr><th><span class=\"kw-chiffre\">1ère ligne</span> — monothérapie <span class=\"kw-ttt\">BDLA</span></th><td><span class=\"kw-clinique\">Dyspnée</span> quotidienne → <span class=\"kw-ttt\">β2-LA</span> ; Dyspnée OU exacerbation → <span class=\"kw-ttt\">anticholinergique LA</span></td></tr>\n          <tr><th>2nde ligne — bithérapie</th><td><span class=\"kw-clinique\">Dyspnée</span> ± exacerbations → 2 BDLA (β2 + anticholinergique) ; Exacerbations + pas de dyspnée marquée (<span class=\"kw-bio\">mMRC &lt; 2</span>) → <span class=\"kw-ttt\">CSI + β2-LA</span></td></tr>\n          <tr><th>3ème ligne — <span class=\"kw-ttt\">trithérapie</span></th><td>Exacerbations malgré bithérapie → 2 BDLA + <span class=\"kw-ttt\">CSI</span></td></tr>\n          <tr><th>4ème ligne</th><td><span class=\"kw-ttt\">Théophylline</span> si <span class=\"kw-clinique\">dyspnée</span> ; <span class=\"kw-ttt\">Macrolides</span> si exacerbations</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4. Indications des CSI</h4>\n      <ul>\n        <li>Toujours <strong>en association</strong> à un <span class=\"kw-ttt\">β2-LA</span>, <span class=\"kw-alerte\">jamais en monothérapie</span> ❌</li>\n        <li><span class=\"kw-bio\">VEMS post-BD &lt; <span class=\"kw-chiffre\">70 %</span></span> de la valeur prédite</li>\n        <li>Exacerbateurs fréquents : <span class=\"kw-chiffre\">≥ 2 exacerbations/an</span></li>\n        <li>Pas de <span class=\"kw-clinique\">dyspnée</span> marquée (<span class=\"kw-bio\">mMRC &lt; 2</span>)</li>\n        <li>Malgré <span class=\"kw-ttt\">BDLA</span> bien conduits</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-clinique\">Les</span> CSI exposent à un risque accru d'infections respiratoires parenchymateuses</strong> ⚠. Bénéfice/risque à peser au cas par cas.\n      </div>\n\n      <h4>5. Médicaments à NE PAS utiliser ❌</h4>\n      <table >\n        <thead><tr><th>Médicament</th><th>Statut</th></tr></thead>\n        <tbody>\n          <tr><th><span class=\"kw-ci\">Corticothérapie orale de fond</span></th><td>Non recommandée</td></tr>\n          <tr><th><span class=\"kw-ci\">CSI en monothérapie</span></th><td>Interdits</td></tr>\n          <tr><th><span class=\"kw-ci\">Mucomodificateurs</span>, anti-leucotriènes, anti-tussifs</th><td>Aucun intérêt</td></tr>\n          <tr><th><span class=\"kw-ttt\">β-bloquants</span> ⭐⭐⭐</th><td><strong>PLUS DE CI FORMELLE</strong> dans la BPCO si l'indication cardiologique est importante</td></tr>\n          <tr><th>Si IRC</th><td>Prudence avec <span class=\"kw-ci\">BZD</span>, <span class=\"kw-ci\">neuroleptiques sédatifs</span>, <span class=\"kw-ci\">opiacés</span> — <span class=\"kw-def\">surveillance</span> gazométrique si indispensables</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Mythe à corriger : <span class=\"kw-clinique\">les</span> β-bloquants ne sont plus <span class=\"kw-ci\">contre-indiqués</span> en BPCO.</strong> Si l'indication CV est forte (coronarien, IC), les prescrire — le bénéfice CV l'emporte.\n      </div>\n\n      <h4>6. Réhabilitation respiratoire</h4>\n      <ul>\n        <li><strong>Indication</strong> : dès qu'il existe un handicap persistant (y compris <span class=\"kw-clinique\">dyspnée</span> seule) malgré le traitement, <strong>quel que soit le <span class=\"kw-def\">stade</span></strong></li>\n        <li><strong>2 composantes essentielles</strong> : ré-entraînement à l'effort + <span class=\"kw-def\">éducation thérapeutique</span> (<span class=\"kw-ttt\">ETP</span>)</li>\n        <li>Activités associées : <span class=\"kw-ttt\">sevrage</span> tabac ; bilan nutritionnel ; PEC psycho-sociale ; kinésithérapie de <span class=\"kw-ttt\">drainage</span> bronchique</li>\n        <li>À proposer dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">90 jours</span> suivant une <span class=\"kw-alerte\">hospitalisation</span> pour exacerbation</li>\n      </ul>\n\n      <h4>7. <span class=\"kw-ttt\">Oxygénothérapie</span> longue durée (OLD)</h4>\n      <p>Indication = <span class=\"kw-clinique\">IRC documentée</span>. Mesure essentielle qui <strong>diminue la <span class=\"kw-def\">mortalité</span></strong>.</p>\n      <table >\n        <thead><tr><th>Type d'IRC</th><th><span class=\"kw-def\">Critère de</span> remboursement</th></tr></thead>\n        <tbody>\n          <tr><th>IRC restrictive</th><td><span class=\"kw-bio\">PaO2 &lt; <span class=\"kw-chiffre\">60 mmHg</span></span></td></tr>\n          <tr>\n            <th>IRC obstructive</th>\n            <td>\n              <strong>Seuil franc :</strong> <span class=\"kw-bio\">PaO2 &lt; <span class=\"kw-chiffre\">55 mmHg</span></span><br>\n              <strong>Seuil intermédiaire :</strong> <span class=\"kw-bio\">PaO2</span> <span class=\"kw-chiffre\">55-60 mmHg</span> + signe(s) d'hypoxie tissulaire — <span class=\"kw-bio\">Polyglobulie</span> (Ht &gt; <span class=\"kw-chiffre\">55 %</span>) ; <span class=\"kw-clinique\">IVD / HTAP</span> ; désaturations nocturnes non apnéiques (<span class=\"kw-bio\">SpO2 nocturne moyenne ≤ <span class=\"kw-chiffre\">88 %</span></span>)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>⚠️ <span class=\"kw-alerte\">PaO2 mesurée 2× à l'état stable à ≥ 2 semaines d'intervalle</span> ⭐⭐⭐</strong></p>\n      <ul>\n        <li><strong>Modalités</strong> : domicile ; lunettes nasales ; idéalement <span class=\"kw-chiffre\">24h/24</span> (minimum <span class=\"kw-chiffre\">≥ 15 h/j</span>) couvrant nuit + activité physique. Objectif : <span class=\"kw-bio\">PaO2 &gt; <span class=\"kw-chiffre\">60 mmHg</span></span> ou <span class=\"kw-bio\">SpO2 &gt; <span class=\"kw-chiffre\">90 %</span></span>.</li>\n        <li><strong><span class=\"kw-ci\">CI absolue</span></strong> : <span class=\"kw-alerte\">tabagisme actif persistant</span> (risque de brûlures graves voire incendie). L'<span class=\"kw-clinique\">hypercapnie</span> N'EST PAS une CI à l'OLD si corrigée par <span class=\"kw-ttt\">VNI</span> à domicile.</li>\n      </ul>\n\n      <h4>8. Ventilation à domicile (<span class=\"kw-ttt\">VNI</span> au long cours)</h4>\n      <ul>\n        <li><strong>Principe</strong> : assistance des muscles inspiratoires par pression positive pour corriger l'hypoventilation alvéolaire (surtout nocturne)</li>\n        <li><strong>IRC obstructive</strong> : indiquée si <span class=\"kw-clinique\">hypercapnie diurne</span> importante → améliore survie, qualité de vie, <span class=\"kw-clinique\">dyspnée</span>, fréquence des hospitalisations</li>\n        <li><strong>Modalités</strong> : masque nasal ou naso-buccal, la nuit (± journée pour neuromusculaires)</li>\n      </ul>\n\n      <h4>9. Traitement de l'exacerbation aiguë (hospitalisée)</h4>\n      <p>Cf. <strong>obj-9</strong> pour <span class=\"kw-clinique\">les</span> 4 étapes (O2 → conditionnement → BDCA → <span class=\"kw-ttt\">VNI</span>).</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span> BPCO</th><th>Indication ATB</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr><th>VEMS &gt; <span class=\"kw-chiffre\">50 %</span> + pas de <span class=\"kw-clinique\">dyspnée</span></th><td>Pas d'ATB</td><td>—</td></tr>\n          <tr>\n            <th>VEMS &lt; <span class=\"kw-chiffre\">50 %</span> + <span class=\"kw-clinique\">dyspnée</span> d'effort</th>\n            <td>Si <span class=\"kw-bio\">expectoration franchement purulente verdâtre</span></td>\n            <td><span class=\"kw-ttt\">Amoxicilline</span> OU <span class=\"kw-ttt\">macrolide</span> OU <span class=\"kw-ttt\">pristinamycine</span></td>\n          </tr>\n          <tr>\n            <th>VEMS &lt; <span class=\"kw-chiffre\">30 %</span> + <span class=\"kw-clinique\">dyspnée</span> au moindre effort/repos</th>\n            <td><strong>Systématique</strong></td>\n            <td><span class=\"kw-ttt\">Amoxicilline-acide clavulanique</span> OU <span class=\"kw-ttt\">C3G injectables</span> (<span class=\"kw-ttt\">céfotaxime</span>, <span class=\"kw-ttt\">ceftriaxone</span>) OU en dernier recours <span class=\"kw-ttt\">FQAP</span> (<span class=\"kw-ttt\">lévofloxacine</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Durée</strong> : <span class=\"kw-chiffre\">5 jours</span> (parfois 5-7 j)</li>\n        <li><strong><span class=\"kw-def\">Réévaluation</span> systématique à <span class=\"kw-chiffre\">J2-J3</span></strong> ; introduction d'ATB si aggravation sous <span class=\"kw-def\">surveillance</span></li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ FQAP <span class=\"kw-ci\">interdite</span> si <span class=\"kw-ttt\">fluoroquinolone</span> reçue dans <span class=\"kw-clinique\">les</span> 3 derniers mois.</strong>\n      </div>\n\n      <h4>10. <span class=\"kw-ttt\">Corticothérapie</span> systémique de l'exacerbation</h4>\n      <ul>\n        <li><strong>Prescrite au cas par cas en <span class=\"kw-alerte\">hospitalisation</span></strong> (améliore VEMS + raccourcit hospitalisation)</li>\n        <li>Dose : <span class=\"kw-chiffre\">30-40 mg/j</span> de <span class=\"kw-ttt\">prednisone</span> ; durée <span class=\"kw-chiffre\">5 jours</span> ; <strong>sans décroissance</strong></li>\n        <li>Ambulatoire : 2nde intention si pas d'amélioration à <span class=\"kw-chiffre\">48 h</span></li>\n      </ul>\n\n      <h4>11. Mesures associées</h4>\n      <ul>\n        <li>Traitement étiologique du facteur déclenchant</li>\n        <li>Arrêt du tabac ; <span class=\"kw-ci\">vaccinations à jour</span></li>\n        <li>Kinésithérapie de <span class=\"kw-ttt\">drainage</span> bronchique si encombrement</li>\n        <li>Prévention de la MTEV (<span class=\"kw-ttt\">HBPM</span> préventive) chez <span class=\"kw-clinique\">les</span> hospitalisés</li>\n      </ul>\n\n      <h4>12. Autres traitements (formes sévères / complications)</h4>\n      <ul>\n        <li><strong>Transplantation pulmonaire</strong> : forme terminale</li>\n        <li><strong><span class=\"kw-ttt\">Réduction</span> de volume pulmonaire</strong> (endoscopique ou bullectomie chirurgicale) : réduire la distension pour améliorer la <span class=\"kw-clinique\">dyspnée</span> — bullectomie si bulles de grande taille / compliquées (infection, hémorragie, PNO) / compressives</li>\n      </ul>\n\n      <h4>13. <span class=\"kw-def\">Suivi</span></h4>\n      <ul>\n        <li>Toute exacerbation = motif de <strong>renforcement du <span class=\"kw-def\">suivi</span></strong> clinique et EFR</li>\n        <li>Consultation médecin traitant dans la <strong>semaine</strong> suivant une exacerbation</li>\n        <li><span class=\"kw-bio\">EFR annuelle</span> minimum</li>\n        <li><span class=\"kw-def\">Réévaluation</span> <span class=\"kw-chiffre\">1-3 mois</span> après chaque changement thérapeutique, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-12 mois</span></li>\n        <li>Réhabilitation respiratoire dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">90 jours</span> post-exacerbation</li>\n      </ul>\n\n      <div class=\"callout callout-danger\">\n        <strong>🚨 <span class=\"kw-ttt\">Sevrage</span> tabagique = unique mesure modifiant l'histoire naturelle de la BPCO.</strong> Tout le reste (<span class=\"kw-ttt\">BDLA</span>, <span class=\"kw-ttt\">CSI</span>, <span class=\"kw-ttt\">OLD</span>, <span class=\"kw-ttt\">VNI</span>…) est symptomatique.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 154 — Infection bronchopulmonaire communautaire · 75 — Addiction Tabac · 208 — <span class=\"kw-ci\">Insuffisance respiratoire</span> chronique</em></p>","frequence":5}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class=\"kw-alerte\">exacerbation sévère</span> = engage le <span class=\"kw-alerte\">pronostic vital</span> (<span class=\"kw-alerte\">DRA</span>, <span class=\"kw-alerte\">hypoxémie profonde</span>, <span class=\"kw-alerte\">acidose respiratoire décompensée</span>)<br><strong>Fenêtre :</strong> <span class=\"kw-alerte\">hypoxémie grave non traitée</span> = <span class=\"kw-alerte\">urgence</span> immédiate (<span class=\"kw-alerte\">arrêt cardiaque</span> hypoxique) ; <span class=\"kw-clinique\">hypercapnie</span> = urgence différée (dizaines de min à heures)<br><strong>1er geste :</strong> <span class=\"kw-ttt\">oxygénothérapie</span> titrée pour <span class=\"kw-chiffre\">SpO2 88-92%</span> (motif d'<span class=\"kw-alerte\">hospitalisation</span>)</p>","hospit":"<p><strong>Ambulatoire :</strong> pas de <span class=\"kw-alerte\">signe de gravité</span> (majorité des cas), sans explorations complémentaires<br><strong>Hospit :</strong> <span class=\"kw-def\">BPCO stade 3-4</span>, <span class=\"kw-clinique\">dyspnée</span> à l'état basal, <span class=\"kw-clinique\">arythmie</span>, âge <span class=\"kw-chiffre\">&gt; 70 ans</span>, <span class=\"kw-def\">comorbidités</span>, échec du traitement initial, OLD/ventilation à domicile, ATCD de <span class=\"kw-alerte\">réanimation</span><br><strong>Réa / <span class=\"kw-ttt\">VNI</span> :</strong> <span class=\"kw-alerte\">acidose respiratoire</span> (<span class=\"kw-chiffre\">pH &lt; 7,35</span>) ou signes de <span class=\"kw-alerte\">DRA</span></p>","redflags":"<ul><li><span class=\"kw-alerte\">Détresse respiratoire</span> : <span class=\"kw-clinique\">tachypnée</span>, difficulté à la parole, <span class=\"kw-clinique\">cyanose</span></li><li><span class=\"kw-alerte\">Balancement thoraco-abdominal</span> (paradoxe abdominal avec <span class=\"kw-clinique\">tachypnée</span>)</li><li><span class=\"kw-alerte\">Bradypnée</span> = faillite diaphragmatique → recours urgent à la <span class=\"kw-ttt\">ventilation mécanique</span></li><li><span class=\"kw-alerte\">Détresse</span> cardiovasculaire : <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">sueurs</span> (signes d'hypercapnie)</li><li>Hypoperfusion périphérique : froideur des extrémités, <span class=\"kw-clinique\">marbrures</span>, pouls filants (hypoxie tissulaire)</li><li>Paraclinique : <span class=\"kw-bio\">acidose respiratoire</span> (<span class=\"kw-chiffre\">pH &lt; 7,35</span>)</li></ul>","principes":"<p>Exacerbation : traiter en <span class=\"kw-alerte\">urgence</span> (O2, BDCA, ± <span class=\"kw-ttt\">VNI</span>/ATB/CTC) puis optimiser le traitement de fond par paliers.</p><p><strong>Exacerbation — traitement symptomatique (par étapes)</strong></p><p><span class=\"kw-alerte\">Hypoxémie grave = urgence immédiate</span> ; <span class=\"kw-ci\">ne jamais</span> sous-doser l'O2 par crainte de l'hypercapnie</p><ul><li><span class=\"kw-ttt\">O2</span> titré pour <span class=\"kw-chiffre\">SpO2 88-92%</span> (débit élevé d'emblée si hypoxémie profonde, puis titré) ; <span class=\"kw-def\">surveillance</span> gazométrique si <span class=\"kw-clinique\">hypercapnie</span></li><li><span class=\"kw-ttt\">BDCA</span> inhalés/nébulisés : <span class=\"kw-ttt\">β2-agonistes courte action</span> (<span class=\"kw-ttt\">salbutamol</span>/<span class=\"kw-ttt\">terbutaline</span> <span class=\"kw-chiffre\">5 mg, 4-6×/j</span>) ± <span class=\"kw-ttt\">anticholinergiques</span> (<span class=\"kw-ttt\">ipratropium</span> <span class=\"kw-chiffre\">0,5 mg, 3-4×/j</span>)</li><li><span class=\"kw-ttt\">VNI</span> si <span class=\"kw-alerte\">acidose respiratoire</span> (<span class=\"kw-chiffre\">pH &lt; 7,35</span>) ou <span class=\"kw-alerte\">signes de gravité</span> ; <span class=\"kw-ttt\">intubation</span> si échec ou CI</li><li><span class=\"kw-ttt\">Corticothérapie systémique</span> <span class=\"kw-chiffre\">30-40 mg/j</span> pendant <span class=\"kw-chiffre\">5 jours</span> sans décroissance (ambulatoire : 2nde intention si pas d'amélioration à <span class=\"kw-chiffre\">48h</span>)</li></ul><p><strong><span class=\"kw-ttt\">Antibiothérapie</span> de l'exacerbation</strong></p><ul><li>Indication : <span class=\"kw-clinique\">majoration de la purulence</span> des <span class=\"kw-clinique\">expectorations</span> (critère principal) ; <span class=\"kw-def\">BPCO très sévère</span> (<span class=\"kw-chiffre\">VEMS &lt; 30%</span>) ; <span class=\"kw-alerte\">signes de gravité</span></li><li>Absence de FR : <span class=\"kw-ttt\">amoxicilline</span> ± <span class=\"kw-ttt\">acide clavulanique</span>, <span class=\"kw-ttt\">pristinamycine</span> ou <span class=\"kw-ttt\">macrolide</span></li><li>Présence de FR / forme sévère : <span class=\"kw-ttt\">amox-clav</span>, <span class=\"kw-ttt\">C3G injectable</span> (<span class=\"kw-ttt\">céfotaxime</span>/<span class=\"kw-ttt\">ceftriaxone</span>) ou <span class=\"kw-ttt\">FQAP</span> (<span class=\"kw-ttt\">lévofloxacine</span>)</li><li>Durée <span class=\"kw-chiffre\">5 jours</span> (5-7 j) ; <span class=\"kw-def\">réévaluation</span> systématique à <span class=\"kw-chiffre\">J2-J3</span></li><li><span class=\"kw-ci\">FQAP contre-indiquée</span> si une <span class=\"kw-ttt\">fluoroquinolone</span> a été reçue dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 derniers mois</span></li></ul><p><strong>Traitement de fond (paliers)</strong></p><ul><li>À tous stades : <span class=\"kw-ttt\">BDCA</span> à la demande si <span class=\"kw-clinique\">dyspnée</span></li><li><span class=\"kw-chiffre\">1ère ligne</span> (monothérapie BDLA) : <span class=\"kw-ttt\">β2-LA</span> si <span class=\"kw-clinique\">dyspnée</span> ; <span class=\"kw-ttt\">anticholinergique LA</span> si dyspnée ou exacerbations</li><li>2nde ligne (bithérapie) : association de <span class=\"kw-ttt\">2 BDLA</span> ; ou <span class=\"kw-ttt\">CSI + β2-LA</span> si exacerbations sans <span class=\"kw-clinique\">dyspnée</span> importante (<span class=\"kw-chiffre\">mMRC &lt; 2</span>)</li><li>3ème ligne (<span class=\"kw-ttt\">trithérapie</span>) : <span class=\"kw-ttt\">2 BDLA + CSI</span> si exacerbations malgré la bithérapie</li><li><span class=\"kw-ci\">À ne pas utiliser</span> : <span class=\"kw-ttt\">corticothérapie</span> orale au long cours, CSI en monothérapie, mucomodificateurs, antitussifs</li></ul><p><strong>Mesures de fond non médicamenteuses</strong></p><ul><li><span class=\"kw-ttt\">Sevrage tabagique</span> = seule mesure modifiant l'histoire naturelle</li><li>Vaccinations : <span class=\"kw-ttt\">anti-grippal</span> annuel, <span class=\"kw-ttt\">anti-pneumococcique</span> (VPC13 puis VPP23 à<span class=\"kw-chiffre\"> 2 mois</span>), <span class=\"kw-ttt\">anti-COVID</span></li><li><span class=\"kw-ttt\">Réhabilitation respiratoire</span> (réentraînement à l'exercice + <span class=\"kw-def\">ETP</span>)</li><li>Activité physique <span class=\"kw-chiffre\">30 min/j</span> ; <span class=\"kw-ttt\">HBPM préventive</span> si <span class=\"kw-alerte\">hospitalisation</span></li><li><span class=\"kw-ttt\">Oxygénothérapie longue durée</span> si <span class=\"kw-chiffre\">PaO2 &lt; 55 mmHg</span> (ou <span class=\"kw-chiffre\">55-60 mmHg</span> + signes d'hypoxie tissulaire) ; <span class=\"kw-ttt\">ventilation à domicile</span> si hypercapnie diurne</li></ul>","suivi":"<p><strong>ATB :</strong> <span class=\"kw-def\">réévaluation</span> systématique à <span class=\"kw-chiffre\">J2-J3</span><br><strong>Post-exacerbation :</strong> consultation du médecin traitant dans la <span class=\"kw-chiffre\">semaine</span> ; réadaptation respiratoire dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">90 jours</span> suivant une <span class=\"kw-alerte\">hospitalisation</span><br><strong>EFR :</strong> spirométrie à distance, <span class=\"kw-chiffre\">annuelle</span> au minimum<br><strong>Traitement de fond :</strong> réévaluation <span class=\"kw-chiffre\">1-3 mois</span> après chaque changement, puis tous les <span class=\"kw-chiffre\">3-12 mois</span></p>"},"liensGlobaux":[{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_209_BRONCHOPNEUMOPATHIE_CHRONIQUE_OBSTRUCTIVE_2023.pdf","label":"Collège (CEP) — Item 209 bronchopneumopathie chronique obstructive 2023"},{"href":"https://radiopaedia.org/articles/chronic-obstructive-pulmonary-disease-1","label":"Radiopaedia : Chronic obstructive pulmonary disease 1"},{"href":"http://semiologiepneumologique.com/ANNEXE/index.php?idnote=51","label":"**51**"},{"href":"http://semiologiepneumologique.com/ANNEXE/index.php?idnote=57","label":"**57**"},{"href":"http://semiologiepneumologique.com/ANNEXE/index.php?idnote=55","label":"**55**"},{"href":"http://semiologiepneumologique.com/ANNEXE/index.php?idnote=59","label":"**59**"},{"href":"http://semiologiepneumologique.com/ANNEXE/index.php?idnote=61","label":"**61**"},{"href":"https://www.inanutshell.ch/fr/calculateurs/echelle-de-dyspnee-mmrc/","label":"In a Nutshell — Echelle de dyspnee mmrc"},{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/22.%20Insuffisance%20respiratoire%20aigu%C3%AB%20du%20patient%20BPCO.pdf","label":"CeMIR — 22. insuffisance respiratoire aiguë du patient bpco"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Exacerbation de BPCO — Aggravation durable des symptômes respiratoires (> 24h)","detail":"<h4>CAT — Exacerbation de BPCO — Orientation et <span class=\"kw-ttt\">antibiothérapie</span> selon gravité et purulence</h4>","branches":[{"to":"q-gravite","label":"Évaluer la gravité","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"<span class=\"kw-alerte\">Signes de gravité</span> ? — DRA, hypoxémie profonde, acidose respiratoire (<span class=\"kw-bio\">pH</span> <span class=\"kw-chiffre\">< 7,35</span>)","branches":[{"to":"t-rea","label":"Oui — détresse / acidose (pH < 7,35)","color":"red"},{"to":"q-hospit","label":"Non","color":"green"}]},{"id":"t-rea","kind":"terminal","label":"Hospitalisation — O2 titré + VNI","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">O2</span> titré pour <span class=\"kw-chiffre\">SpO2 88-92%</span> (débit élevé d'emblée si hypoxémie profonde)</li><li><span class=\"kw-ttt\">BDCA</span> nébulisés (<span class=\"kw-ttt\">salbutamol</span>/<span class=\"kw-ttt\">terbutaline</span> ± <span class=\"kw-ttt\">ipratropium</span>)</li><li><span class=\"kw-ttt\">VNI</span> si <span class=\"kw-chiffre\">pH &lt; 7,35</span> ; <span class=\"kw-ttt\">intubation</span> si échec ou CI</li><li><span class=\"kw-ttt\">Corticothérapie systémique</span> <span class=\"kw-chiffre\">30-40 mg/j</span> sur <span class=\"kw-chiffre\">5 j</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Gazométrie</span> répétée (dépister une aggravation de l'acidose sous O2)</li><li>Scope <span class=\"kw-imagerie\">ECG</span>, PA non invasive, accès veineux</li></ul>"},{"id":"q-hospit","kind":"decision","label":"Critères d'hospitalisation ? — Stade 3-4, âge > 70 ans, comorbidités, échec du traitement initial","branches":[{"to":"t-hospit","label":"Oui","color":"amber"},{"to":"q-purulence","label":"Non — maintien ambulatoire","color":"green"}]},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation conventionnelle","color":"amber","detail":"<h4>Conduite</h4><ul><li>Bilan systématique : <span class=\"kw-bio\">ECG, GDS, RXT, NFS, CRP, ionogramme, créatinine</span></li><li><span class=\"kw-ttt\">O2</span> si besoin (<span class=\"kw-chiffre\">SpO2 88-92%</span>), <span class=\"kw-ttt\">BDCA</span> nébulisés ± <span class=\"kw-ttt\">corticothérapie</span></li><li><span class=\"kw-ttt\">Antibiothérapie</span> selon purulence et gravité</li></ul><h4>Indications</h4><ul><li><span class=\"kw-def\">BPCO stade 3-4</span>, <span class=\"kw-clinique\">dyspnée</span> à l'état basal, <span class=\"kw-clinique\">arythmie</span></li><li>Âge <span class=\"kw-chiffre\">&gt; 70 ans</span>, <span class=\"kw-def\">comorbidités</span>, absence de soutien à domicile, OLD/ventilation à domicile</li><li>Échec du traitement initial, incertitude diagnostique, ATCD de <span class=\"kw-alerte\">réanimation</span></li></ul>"},{"id":"q-purulence","kind":"decision","label":"Majoration de la purulence des expectorations ? — Critère principal de décision d'antibiothérapie","branches":[{"to":"t-noatb","label":"Expectoration non purulente","color":"green"},{"to":"q-fr","label":"Purulence franche verdâtre","color":"amber"}]},{"id":"t-noatb","kind":"terminal","label":"Ambulatoire sans antibiotique","color":"green","detail":"<h4>Conduite</h4><ul><li>Majoration des <span class=\"kw-ttt\">BDCA</span> inhalés (chambre d'inhalation)</li><li><span class=\"kw-ci\">Pas d'antibiothérapie</span></li><li>Traitement du facteur déclenchant, arrêt du tabac</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> clinique à <span class=\"kw-chiffre\">48h</span></li><li>Si aggravation : introduire une <span class=\"kw-ttt\">antibiothérapie</span></li><li><span class=\"kw-ttt\">Corticothérapie</span> en 2nde intention si pas d'amélioration à <span class=\"kw-chiffre\">48h</span></li></ul>"},{"id":"q-fr","kind":"decision","label":"<span class=\"kw-def\">Facteurs de risque</span> de complication ? — VEMS < 50%, > 2 exacerbations/an, cardiopathie <span class=\"kw-etio\">ischémique</span>, OLD, <span class=\"kw-ttt\">corticothérapie</span> orale chronique","branches":[{"to":"t-atb-simple","label":"Absence de FR","color":"green"},{"to":"t-atb-fr","label":"Présence de FR","color":"amber"}]},{"id":"t-atb-simple","kind":"terminal","label":"Ambulatoire + antibiotique (absence de FR)","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Amoxicilline</span> ± <span class=\"kw-ttt\">acide clavulanique</span> <span class=\"kw-chiffre\">3 g/j</span>, <span class=\"kw-ttt\">pristinamycine</span> <span class=\"kw-chiffre\">3 g/j</span> ou <span class=\"kw-ttt\">macrolide</span></li><li>Durée <span class=\"kw-chiffre\">5 jours</span></li><li>Majoration des <span class=\"kw-ttt\">BDCA</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> systématique à <span class=\"kw-chiffre\">48h (J2-J3)</span></li></ul>"},{"id":"t-atb-fr","kind":"terminal","label":"Ambulatoire + antibiotique (présence de FR) — évaluer hospit","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Amox-clav</span> <span class=\"kw-chiffre\">3 g/j</span>, <span class=\"kw-ttt\">C3G injectable</span> (<span class=\"kw-ttt\">céfotaxime</span>/<span class=\"kw-ttt\">ceftriaxone</span>) ou <span class=\"kw-ttt\">FQAP</span> (<span class=\"kw-ttt\">lévofloxacine</span>)</li><li>Durée <span class=\"kw-chiffre\">5 jours</span></li><li><span class=\"kw-ci\">FQAP contre-indiquée</span> si <span class=\"kw-ttt\">fluoroquinolone</span> reçue dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 derniers mois</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> à <span class=\"kw-chiffre\">48h</span> ; évaluer la nécessité d'une <span class=\"kw-alerte\">hospitalisation</span></li></ul>"}]},"cards":[{"i":"3631e40eaadb","n":209,"o":"209-1","u":"Définition","t":"Connaître la définition de la bronchopneumopathie chronique obstructive (BPCO)","q":"Comment est caractérisé le Trouble Ventilatoire Obstructif (TVO) de la BPCO ?","a":"<p>Le TVO de la BPCO est caractérisé par sa <strong>persistance après l'administration de bronchodilatateurs</strong>. La réversibilité peut être significative (augmentation du VEMS > 200 mL et > 12 % de la valeur initiale) mais <strong>jamais complète</strong>. Une normalisation complète du VEMS après bronchodilatateurs exclut le diagnostic de BPCO.</p>"},{"i":"b1eae09fb092","n":209,"o":"209-1","u":"Définition","t":"Connaître la définition de la bronchopneumopathie chronique obstructive (BPCO)","q":"Quels sont les différents symptômes respiratoires chroniques permettant de poser le diagnostic de BPCO ?","a":"<ul><li><strong>Dyspnée d'effort</strong></li><li><strong>Toux chronique</strong></li><li><strong>Expectoration chronique</strong></li><li><strong>Infections respiratoires basses répétées ou traînantes</strong></li></ul>"},{"i":"e5af67c20aa3","n":209,"o":"209-1","u":"Définition","t":"Connaître la définition de la bronchopneumopathie chronique obstructive (BPCO)","q":"Quelle est la définition de la Bronchopneumopathie Chronique Obstructive (BPCO) ?","a":"<p>La BPCO est une maladie respiratoire chronique, évitable et traitable, définie par l'association de <strong>symptômes respiratoires chroniques</strong> et d'un <strong>trouble ventilatoire obstructif (TVO) persistant</strong> après bronchodilatateurs.</p>"},{"i":"2b348244d453","n":209,"o":"209-10","u":"Prise en charge","t":"Connaître les principes de l’initiation du traitement symptomatique en urgence","q":"Quand la ventilation mécanique est-elle indiquée en urgence chez un patient BPCO, quelle en est la première intention, et quelles sont les particularités du coma hypercapnique ?","a":"<p>La ventilation mécanique est indiquée en cas de <strong>hospitalisation</strong> si :</p><ul><li><strong>Acidose respiratoire</strong> (pH < 7,35) et/ou <strong>signes de gravité</strong>.</li><li><strong>Première intention :</strong> <strong>Ventilation Non Invasive (VNI)</strong> par masque facial.</li><li><strong>Si échec ou contre-indication à la VNI :</strong> <strong>Intubation endotrachéale</strong>.</li><li><strong>Particularité du coma hypercapnique :</strong> Ce n'est <strong>PAS une contre-indication</strong> à la VNI, car il peut être réversible avec une VNI bien conduite.</li></ul>"},{"i":"37cf1cb4eb1e","n":209,"o":"209-10","u":"Prise en charge","t":"Connaître les principes de l’initiation du traitement symptomatique en urgence","q":"Quels sont les bronchodilatateurs de courte action (BDCA) recommandés en première intention et en association pour le traitement d'urgence de la BPCO, et leurs modes d'administration ?","a":"<p>Les BDCA sont un traitement essentiel, administré exclusivement par voie inhalée :</p><ul><li><strong>Première intention :</strong> <strong>β2-agonistes courte durée</strong> comme le <strong>salbutamol 5 mg</strong> ou la <strong>terbutaline 5 mg</strong>, administrés 4 à 6 fois par jour.</li><li><strong>Association possible :</strong> <strong>Anti-cholinergiques courte durée</strong> comme le <strong>bromure d'ipratropium 0,5 mg</strong>, administrés 3 à 4 fois par jour.</li><li><strong>Modes d'administration :</strong> Par <strong>nébulisation</strong> à l'hôpital ; par <strong>chambre d'inhalation</strong> à domicile.</li></ul>"},{"i":"60a3ea593340","n":209,"o":"209-10","u":"Prise en charge","t":"Connaître les principes de l’initiation du traitement symptomatique en urgence","q":"Quels sont le motif, l'objectif, et la surveillance de l'oxygénothérapie en urgence chez un patient BPCO ?","a":"<ul><li><strong>Motif :</strong> Hospitalisation</li><li><strong>Objectif :</strong> Obtenir une SpO2 entre <strong>88 et 92 %</strong>. Le débit doit être titré, en évitant l'administration de haut débit d'oxygène \"à l'aveugle\".</li><li><strong>Surveillance :</strong> Réalisation de Gaz du Sang (GDS) en cas d'hypercapnie, pour détecter une éventuelle aggravation rare de l'acidose respiratoire.</li></ul>"},{"i":"9c8c1e1e1327","n":209,"o":"209-10","u":"Prise en charge","t":"Connaître les principes de l’initiation du traitement symptomatique en urgence","q":"Quel est le piège classique lié à l'oxygénothérapie chez le patient BPCO et pourquoi doit-il être évité ?","a":"<p>Le piège classique est l'<strong>administration insuffisante d'O2</strong> par peur de majorer l'hypercapnie. C'est une erreur à éviter car l'<strong>hypoxémie grave non traitée est une urgence immédiate</strong> pouvant entraîner un arrêt cardiaque hypoxique. L'hypercapnie, en revanche, est une urgence différée.</p>"},{"i":"b17a451ea29a","n":209,"o":"209-10","u":"Prise en charge","t":"Connaître les principes de l’initiation du traitement symptomatique en urgence","q":"Quel est le conditionnement à mettre en place en urgence chez un patient présentant une exacerbation de BPCO ?","a":"<p>Le conditionnement d'un patient en exacerbation de BPCO inclut :</p><ul><li>Patient au <strong>repos</strong>.</li><li>Position <strong>demi-assise</strong>.</li><li>Mise en place d'un <strong>monitoring ECG</strong> et de la <strong>Pression Artérielle (PA) non invasive</strong>.</li><li>Pose d'une <strong>voie veineuse périphérique</strong>.</li></ul>"},{"i":"cf5f2a2b8aeb","n":209,"o":"209-10","u":"Prise en charge","t":"Connaître les principes de l’initiation du traitement symptomatique en urgence","q":"Quelles sont les 4 étapes hiérarchisées du traitement symptomatique en urgence de la BPCO ?","a":"<p>Les 4 étapes hiérarchisées du traitement symptomatique en urgence de la BPCO dans le cadre d'une exacerbation sont :</p><ul><li><strong>Oxygénothérapie</strong></li><li><strong>Conditionnement</strong></li><li><strong>Bronchodilatateurs Courte Action (BDCA)</strong></li><li><strong>Ventilation mécanique si besoin</strong></li></ul>"},{"i":"de57e3ceb5df","n":209,"o":"209-10","u":"Prise en charge","t":"Connaître les principes de l’initiation du traitement symptomatique en urgence","q":"Quels sont les 3 mécanismes expliquant l'hypercapnie sous oxygénothérapie chez un patient BPCO ?","a":"<p>Les 3 mécanismes expliquant l'hypercapnie sous oxygénothérapie sont :</p><ul><li><strong>Effet espace mort :</strong> La levée de la vasoconstriction hypoxique entraîne une perfusion de zones d'espace mort alvéolaire, diminuant l'élimination du CO2.</li><li><strong>Effet Haldane :</strong> L'hémoglobine, mieux saturée en oxygène, a une affinité diminuée pour le CO2, ce qui entraîne une libération de CO2 dans le sang.</li><li><strong>Hypoventilation pure :</strong> Chez les BPCO chroniques, la régulation de la ventilation est principalement assurée par les chimiorécepteurs carotidiens sensibles à la PaO2. Une augmentation excessive de la PaO2 sous oxygénothérapie peut supprimer ce stimulus ventilatoire, entraînant une diminution de la ventilation minute et une accumulation de CO2.</li></ul>"},{"i":"0fb40c60f15f","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Quelles sont les vaccinations recommandées chez un patient atteint de BPCO ?","a":"<p>Les vaccinations recommandées chez un patient atteint de BPCO sont :</p><ul><li>Anti-COVID-19 : recommandé.</li><li>Anti-grippal : <strong>annuel</strong>.</li><li>Anti-pneumococcique : <strong>1 dose de VPC13</strong> suivie 2 mois après d'<strong>1 dose de VPP23</strong>. Un rappel à 5 ans est possible si le risque persiste.</li></ul>"},{"i":"3a32f5fd2af8","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Quand peut-on envisager une antibiothérapie lors de l'exacerbation aiguë de BPCO, et quelles sont les molécules de première intention selon la sévérité ?","a":"<p>L'antibiothérapie est envisagée lors de l'exacerbation aiguë de BPCO selon la sévérité :</p><ul><li><strong>VEMS &gt; 50 % et pas de dyspnée</strong> : <strong>Pas d'antibiothérapie</strong>.</li><li><strong>VEMS &lt; 50 % et dyspnée d'effort</strong> : Si expectoration franchement purulente verdâtre, <strong>Amoxicilline</strong> OU <strong>macrolide</strong> OU <strong>pristinamycine</strong>.</li><li><strong>VEMS &lt; 30 % et dyspnée au moindre effort/repos</strong> : Antibiothérapie systématique avec <strong>Amoxicilline-acide clavulanique</strong> OU <strong>C3G injectables</strong> (céfotaxime, ceftriaxone) OU, en dernier recours, <strong>FQAP</strong> (lévofloxacine).</li></ul><p>La durée est de <strong>5 jours</strong> (parfois 5-7 j). Une réévaluation est systématique à J2-J3.</p>"},{"i":"5ebecc869143","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Dans quelles situations les corticoïdes inhalés (CSI) sont-ils indiqués chez un patient BPCO ?","a":"<p>Les corticoïdes inhalés (CSI) sont indiqués, toujours en association à un β2-LA (jamais en monothérapie), sous ces conditions :</p><ul><li><strong>VEMS post-BD &lt; 70 %</strong> de la valeur prédite.</li><li>Patients <strong>exacerbateurs fréquents (≥ 2 exacerbations/an)</strong>.</li><li>Absence de dyspnée marquée (mMRC &lt; 2).</li><li>Malgré des BDLA bien conduits.</li></ul><p>Il faut peser le bénéfice/risque en raison du risque accru d'infections respiratoires parenchymateuses.</p>"},{"i":"677e061d166b","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Quelle est la seule mesure hygiéno-diététique qui modifie l'histoire naturelle de la BPCO et pourquoi est-elle cruciale ?","a":"<p>La seule mesure qui modifie l'histoire naturelle de la BPCO est le <strong>sevrage tabagique</strong>. Elle est cruciale car elle <strong>interrompt la progression de l'obstruction</strong> et retarde l'apparition ou l'aggravation de l'insuffisance respiratoire chronique.</p>"},{"i":"7586d4f26896","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Quelle est la place de la corticothérapie systémique dans le traitement de l'exacerbation aiguë de BPCO ?","a":"<p>La corticothérapie systémique est prescrite au cas par cas en hospitalisation pour l'exacerbation aiguë de BPCO, car elle améliore le VEMS et raccourcit l'hospitalisation. La dose usuelle est de <strong>30-40 mg/jour de prednisone</strong> pour une durée de <strong>5 jours</strong>, sans décroissance.</p><p>En ambulatoire, c'est une seconde intention si pas d'amélioration à 48 heures.</p>"},{"i":"7e941c023d75","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Quels sont les objectifs généraux de la prise en charge thérapeutique de la BPCO ?","a":"<p>Les objectifs thérapeutiques de la BPCO sont doubles :</p><ul><li>Diminuer les handicaps : améliorer la <strong>dyspnée</strong>, la capacité d'exercice et la qualité de vie.</li><li>Réduire les risques futurs : diminuer les <strong>exacerbations</strong> (gravité et hospitalisations), la <strong>mortalité</strong>, le déclin du VEMS et l'évolution vers l'insuffisance respiratoire chronique (IRC).</li></ul>"},{"i":"8818e84591c6","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Quand faut-il envisager une trithérapie (2 BDLA + CSI) dans le traitement de fond de la BPCO ?","a":"<p>Une trithérapie (2 BDLA + CSI) est envisagée lorsque le patient présente des <strong>exacerbations malgré une bithérapie</strong> avec deux bronchodilatateurs de longue durée d'action (β2-LA + anticholinergique LA) bien conduite.</p>"},{"i":"a10366b35f16","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Quels médicaments sont contre-indiqués ou sans intérêt dans le traitement de fond de la BPCO ?","a":"<p>Les médicaments à ne pas utiliser dans la BPCO sont :</p><ul><li>La <strong>corticothérapie orale de fond</strong> (non recommandée).</li><li>Les <strong>CSI en monothérapie</strong> (interdits).</li><li>Les mucomodificateurs, anti-leucotriènes, anti-tussifs (aucun intérêt).</li><li>Les <strong>bêta-bloquants ne sont plus formellement contre-indiqués</strong> si l'indication cardiologique est importante.</li><li>En cas d'IRC, prudence avec les BZD, neuroleptiques sédatifs, opiacés, avec surveillance gazométrique si indispensables.</li></ul>"},{"i":"dfbfe28c64c1","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Quelle est l'indication principale de l'oxygénothérapie longue durée (OLD) chez le patient BPCO et quelles sont ses modalités ?","a":"<p>L'indication principale de l'oxygénothérapie longue durée (OLD) chez le patient BPCO est une <strong>insuffisance respiratoire chronique (IRC) documentée</strong>, car c'est une mesure essentielle qui diminue la mortalité.</p><p>Les modalités sont :</p><ul><li>À domicile, par lunettes nasales.</li><li>Idéalement <strong>24h/24</strong> (minimum ≥ 15h/jour), couvrant la nuit et l'activité physique.</li><li>L'objectif est d'atteindre une PaO2 &gt; 60 mmHg ou une SpO2 &gt; 90 %.</li><li>La <strong>contre-indication absolue est le tabagisme actif persistant</strong>.</li></ul>"},{"i":"f1be1337b993","n":209,"o":"209-11","u":"Prise en charge","t":"Connaître les principes de prise en charge de l’exacerbation et du traitement de fond","q":"Quels sont les principes généraux du traitement de fond inhalé de la BPCO, notamment concernant l'utilisation des corticoïdes inhalés (CSI) ?","a":"<p>Les <strong>bronchodilatateurs de longue durée d'action (BDLA)</strong> sont la base du traitement de fond inhalé de la BPCO. Les <strong>corticoïdes inhalés (CSI) ne sont jamais utilisés en monothérapie</strong> et doivent toujours être associés à un β2-LA.</p>"},{"i":"1671f1c1c054","n":209,"o":"209-2","u":"Définition","t":"Connaître le principal facteur de risque et les co-morbidités fréquemment associées à la BPCO","q":"En dehors des atteintes cardio-vasculaires, quelles sont les autres comorbidités importantes de la BPCO ?","a":"<ul><li><strong>Cancer broncho-pulmonaire</strong> (risque multiplié par 3).</li><li><strong>Ostéoporose</strong>.</li><li><strong>Troubles métaboliques/nutritionnels</strong> : dénutrition ou obésité, déconditionnement musculaire (amyotrophie), anémie.</li><li><strong>Troubles psychiatriques</strong> : anxiété, dépression.</li></ul>"},{"i":"2e7028b758d2","n":209,"o":"209-2","u":"Définition","t":"Connaître le principal facteur de risque et les co-morbidités fréquemment associées à la BPCO","q":"Quel est le principal facteur de risque de la BPCO et son impact sur l'histoire naturelle de la maladie ?","a":"<p>Le principal facteur de risque de la BPCO est le <strong>tabac</strong>, présent dans plus de <strong>80 %</strong> des cas. Il s'agit du seul facteur dont l'arrêt peut modifier l'histoire naturelle de la maladie.</p>"},{"i":"66dc16e08b22","n":209,"o":"209-2","u":"Définition","t":"Connaître le principal facteur de risque et les co-morbidités fréquemment associées à la BPCO","q":"Quelles sont les comorbidités cardio-vasculaires fréquemment associées à la BPCO et leur importance pronostique ?","a":"<p>Les comorbidités cardio-vasculaires fréquentes associées à la BPCO comprennent la <strong>coronaropathie</strong>, l'<strong>insuffisance cardiaque</strong> et l'<strong>hypertension artérielle</strong>. Elles représentent la <strong>première cause de mortalité</strong> chez les patients atteints de BPCO.</p>"},{"i":"0bc123932430","n":209,"o":"209-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel","q":"Dans le diagnostic de la BPCO, comment interprète-t-on la réversibilité bronchique significative ou complète à la spirométrie ?","a":"<ul><li>Une <strong>réversibilité significative</strong> (augmentation du VEMS &gt; 200 mL ET &gt; 12 % par rapport à la valeur initiale après BDCA ou test aux corticoïdes) est « possible » mais ne remet pas en cause le diagnostic de BPCO si le VEMS/CVF post-BD reste &lt; 70%.</li><li>Une <strong>réversibilité complète</strong> (normalisation du VEMS post/CVF post &gt; 0,7 ET VEMS post &gt; 80 %) <strong>exclut la BPCO</strong> et oriente vers l'asthme.</li></ul><p>Attention : le critère de 70 % dans VEMS/CVF est un pourcentage des valeurs mesurées (VEMS mesuré / CVF mesurée), et non un pourcentage de la valeur théorique.</p>"},{"i":"465ef6c4f528","n":209,"o":"209-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel","q":"Quels signes physiques thoraciques peut-on retrouver à l'examen clinique chez un patient présentant une BPCO ?","a":"<p>Les signes physiques de distension ou d'obstruction à rechercher sont :</p><ul><li>Distension thoracique : <strong>thorax en tonneau</strong>, raccourcissement du segment sus-sternal &lt; 3 cm, augmentation du diamètre antéro-postérieur, <strong>position du tripode</strong>.</li><li>Signe de Hoover : diminution du diamètre transversal inférieur du thorax à l'inspiration, témoin de distension.</li><li>Signes d'obstruction : expiration abdominale active, <strong>respiration lèvres pincées</strong>.</li><li>Auscultation : <strong>ronchi</strong>, <strong>sibilants diffus</strong>, sifflements audibles sans stéthoscope.</li></ul>"},{"i":"52a71b0ad7d2","n":209,"o":"209-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel","q":"Quels sont les principaux signes fonctionnels à rechercher à l'interrogatoire pour suspecter une BPCO ?","a":"<p>La suspicion de BPCO doit faire rechercher à l'interrogatoire :</p><ul><li>Une <strong>dyspnée d'effort progressive</strong>, principal symptôme, évaluée par l'échelle <strong>mMRC</strong>.</li><li>Une <strong>toux</strong>, associée ou non à des expectorations.</li><li>Des <strong>infections respiratoires basses répétées</strong> ou traînantes.</li></ul>"},{"i":"578fe0fc6b76","n":209,"o":"209-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel","q":"Comment interpréter les signes de dysfonction diaphragmatique et d'emphysème à l'examen clinique d'un patient BPCO ?","a":"<p>Ces signes sont :</p><ul><li><strong>Signes de dysfonction diaphragmatique</strong> : tirages intercostaux, sus-claviculaires ou sus-sternaux ; <strong>respiration abdominale paradoxale</strong> (signe de gravité en aigu) ; pouls respiratoire palpable ; <strong>signe de Campbell</strong> (descente du cartilage thyroïde à l'inspiration).</li><li><strong>Signes d'emphysème</strong> : diminution bilatérale du murmure vésiculaire.</li></ul>"},{"i":"b6865e43ce99","n":209,"o":"209-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel","q":"Quelles sont les principales différences entre la BPCO et l'asthme, un diagnostic différentiel majeur ?","a":"<ul><li><strong>Définition</strong> : BPCO (obstruction non complètement réversible) vs Asthme (obstruction totalement/presque totalement réversible).</li><li><strong>Terrain</strong> : BPCO (fumeur, &gt; 40 ans) vs Asthme (adulte jeune, atopique).</li><li><strong>Histoire naturelle</strong> : BPCO (aggravation progressive, exacerbations) vs Asthme (début enfance, symptômes variables et réversibles).</li><li><strong>EFR</strong> : BPCO (TVO permanent, spirométrie jamais normale) vs Asthme (TVO réversible, spirométrie peut être normale).</li></ul><p>Il faut noter que BPCO et asthme peuvent être associés.</p>"},{"i":"f9d24348dd32","n":209,"o":"209-3","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic positif et du diagnostic différentiel","q":"Quel examen paraclinique est indispensable pour confirmer le diagnostic de BPCO et quels en sont les critères ?","a":"<p>La confirmation de la BPCO requiert une <strong>spirométrie avec mesure du VEMS et de la CVF avant et après bronchodilatateurs</strong> (post-BD), effectuée en dehors d'une exacerbation.</p><p>Le critère indispensable est un <strong>VEMS/CVF &lt; 70 % post-BD</strong>, témoignant d'un trouble ventilatoire obstructif (TVO) non complètement réversible.</p>"},{"i":"1d760bd4514c","n":209,"o":"209-4","u":"Identifier une urgence","t":"Identifier une exacerbation/décompensation de BPCO, en évaluer les signes de gravité","q":"Quels sont les critères d'orientation vers une hospitalisation pour une exacerbation de BPCO ?","a":"<p>L'hospitalisation doit être envisagée en présence de :</p><ul><li><strong>Signes de gravité immédiate</strong> ou aggravation rapide.</li><li>Dyspnée importante à l'état basal (même pour les activités courantes comme s'habiller).</li><li>Apparition d'une arythmie.</li><li>BPCO sévère (stade <strong>GOLD 3 ou 4</strong>).</li><li>Absence de réponse au traitement initial ou <strong>incertitude diagnostique</strong>.</li><li>Terrain particulier : <strong>âge > 70 ans</strong>, fragilité, absence de soutien à domicile, oxygénothérapie de longue durée (OLD), ventilation à domicile.</li><li>Antécédents ou comorbidités : antécédents de réanimation pour exacerbation, comorbidités cardio-vasculaires, alcoolisme, pathologies neurologiques ou psychiatriques.</li></ul>"},{"i":"24d521f52f4a","n":209,"o":"209-4","u":"Identifier une urgence","t":"Identifier une exacerbation/décompensation de BPCO, en évaluer les signes de gravité","q":"Quels sont les signes de gravité cardio-vasculaire et d'alerte métabolique associés à une exacerbation de BPCO ?","a":"<ul><li><strong>HTA</strong> (hypertension artérielle).</li><li><strong>Sueurs</strong>, qui peuvent être un signe d'hypercapnie.</li><li>Signes d'<strong>hypoperfusion périphérique</strong> : froideur des extrémités, marbrures, pouls filants, témoignant d'une hypoxie tissulaire.</li></ul>"},{"i":"4c90c77f4d52","n":209,"o":"209-4","u":"Identifier une urgence","t":"Identifier une exacerbation/décompensation de BPCO, en évaluer les signes de gravité","q":"De quels signes d'extrême gravité faut-il se méfier lors d'une exacerbation de BPCO ?","a":"<p>Il faut se méfier de l'association <strong>bradypnée et balancement abdominal</strong>, qui signe une faillite diaphragmatique. C'est un signe d'extrême gravité nécessitant une <strong>ventilation mécanique urgente</strong>.</p>"},{"i":"a6064b0d8411","n":209,"o":"209-4","u":"Identifier une urgence","t":"Identifier une exacerbation/décompensation de BPCO, en évaluer les signes de gravité","q":"Quels sont les signes de gravité respiratoire d'une exacerbation de BPCO ?","a":"<ul><li><strong>Tachypnée</strong>.</li><li><strong>Difficulté à la parole</strong> (signe d'essoufflement).</li><li><strong>Cyanose</strong>.</li><li><strong>Balancement thoraco-abdominal</strong> (particulièrement le paradoxe abdominal avec tachypnée).</li><li><strong>Bradypnée</strong>, qui est un signe d'extrême gravité (faillite diaphragmatique) et impose une ventilation mécanique urgente.</li></ul>"},{"i":"b4ed520c8bde","n":209,"o":"209-4","u":"Identifier une urgence","t":"Identifier une exacerbation/décompensation de BPCO, en évaluer les signes de gravité","q":"Quels sont les signes cliniques diagnostiques d'une exacerbation de BPCO ?","a":"<ul><li><strong>Augmentation de la toux</strong>.</li><li><strong>Augmentation de la dyspnée</strong>.</li><li><strong>Modification du volume et/ou de la purulence des expectorations</strong>.</li></ul><p>Ces symptômes doivent évoluer depuis plus de 24 heures et moins de 14 jours, et entraîner une modification thérapeutique (augmentation des bronchodilatateurs de courte durée d'action, corticothérapie systémique, ou antibiotiques).</p>"},{"i":"d5b8a43cf5dc","n":209,"o":"209-4","u":"Identifier une urgence","t":"Identifier une exacerbation/décompensation de BPCO, en évaluer les signes de gravité","q":"Quelle est la définition d'une exacerbation de BPCO ?","a":"<p>Une exacerbation de BPCO est un événement aigu caractérisé par une <strong>aggravation durable (plus de 24 heures et moins de 14 jours)</strong> des symptômes respiratoires habituels, nécessitant une <strong>modification thérapeutique</strong>.</p>"},{"i":"43a745161a3e","n":209,"o":"209-6","u":"Examens complémentaires","t":"Connaître les signes paracliniques de gravité","q":"Comment est définie l'hypoxémie profonde, et quel est son impact en termes de gravité et de prise en charge dans le cadre de la BPCO ?","a":"<p>L'hypoxémie profonde est caractérisée par une <strong>SpO2 ou PaO2 basse</strong>. C'est un <strong>critère de gravité majeur</strong> qui justifie une <strong>oxygénothérapie</strong>.</p>"},{"i":"67614cebe9d6","n":209,"o":"209-6","u":"Examens complémentaires","t":"Connaître les signes paracliniques de gravité","q":"Quelle est l'indication thérapeutique immédiate en présence d'une acidose respiratoire (pH &lt; 7,35) lors d'une exacerbation de BPCO ?","a":"<p>L'indication thérapeutique immédiate et de première intention est la <strong>Ventilation Non Invasive (VNI)</strong>.</p>"},{"i":"8924974178bb","n":209,"o":"209-6","u":"Examens complémentaires","t":"Connaître les signes paracliniques de gravité","q":"Quel est le signe paraclinique de gravité majeur de la BPCO, identifiable sur les Gaz du Sang et justifiant une intervention rapide ?","a":"<p>Le signe paraclinique de gravité majeur est l'<strong>acidose respiratoire</strong>, définie par un <strong>pH &lt; 7,35</strong> sur les gaz du sang artériels.</p>"}]};